-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warlock.dps.Name"] = "Alle Talentbäume"
L["rm.era.warlock.dps.Description"] = "Stufen 1–60, jeder Talentbaum, auch auf Hardcore- und Self-Found-Realms; zusammengestellt aus Wowhead, Icy Veins, Warcraft Tavern und Simulation. Pausiert, während Sie wirken oder kanalisieren, und markiert solo nie einen Gegner, den jemand anderes bekämpft. Schattentrance von Einbruch der Nacht zuerst; Schattenbrand und Sengender Schmerz, um ein Ziel in der Gruppe zu erledigen; ein Solo-Ziel kurz vor dem Tod erhält Seelendieb (für einen Splitter oder mit Verbessertem Seelendieb), Schattenbrand oder Feuersbrunst, dann den Zauberstab, nie neue DoTs. In Bewegung nur Spontanzauber. Gegen drei oder mehr Gegner: Höllenfeuer, wenn sie Sie angreifen und Sie die Hälfte Ihrer Gesundheit haben, sonst Feuerregen. Ein Fluch: in Schlachtzügen Fluch der Schatten oder der Elemente, wenn niemand ihn wirkt, Fluch der Verdammnis bei langen Kämpfen gegen Elitegegner, sonst Fluch der Pein. Feuerbrand, wenn er sich lohnt (Zerstörung, Schlachtzüge oder ab 40 % Mana), Verderbnis, Lebensentzug (in Schlachtzügen nur bei Schattenverwundbarkeit). Solo: Dunkler Pakt, Aderlass bei guter Gesundheit, Blutsauger bei Verletzung, der Zauberstab. Sonst Schattenblitz. Erinnerungen: Dämonenrüstung oder Dämonenhaut, Ihr Begleiter (Leerwandler solo, Wichtel in einer Gruppe, Sukkubus für Dämonische Opferung), Teufelsbeherrschung, Dämonische Opferung, Fluch verstärken, Opferung des Leerwandlers und ein Gesundheitsstein bei niedriger Gesundheit, Lebenslinie. Fluchzuweisungen, Fluch der Tollkühnheit auf einen fliehenden Gegner, Furcht, Verbannen, Seelensteine und das Herstellen von Gesundheitssteinen bleiben Ihnen überlassen."
L["rm.era.warlock.dps.icyveins.Name"] = "Fluch und Verderbnis im Schlachtzug (Icy Veins)"
L["rm.era.warlock.dps.icyveins.Description"] = "Die Liste von Icy Veins für Realms mit dem Limit von 16 Schwächungszaubern, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. In Schlachtzügen nur Ihr Fluch und Verderbnis, dann Schattenblitz, ohne Feuerbrand und ohne Lebensentzug. Leveln und Dungeons spielen sich wie die empfohlene integrierte Rotation."
L["rm.era.warlock.dps.warcrafttavern.Name"] = "Drain-Tanking (Warcraft Tavern)"
L["rm.era.warlock.dps.warcrafttavern.Description"] = "Der Leveling-Stil von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Der Wichtel, ab Stufe 20 dann der Sukkubus. Feuerbrand, Lebensentzug und Verderbnis, dann solo Blutsauger als Füller, sobald Sie seinen vierten Rang erlernen (davor der Zauberstab), Aderlass, wann immer Ihre Gesundheit fast voll ist, und Dunkler Pakt, bevor das Mana Ihres Begleiters voll ist. In Schlachtzügen jeder DoT, den die Plätze erlauben, dann Schattenblitz. Dieselben Finisher, Fluch- und Sicherheitserinnerungen wie die empfohlene integrierte Rotation; einen zweiten Gegner in Furcht zu versetzen bleibt Ihnen überlassen."
L["rm.forever.warlock.dps.Name"] = "Alle Talentbäume"
L["rm.forever.warlock.dps.Description"] = "Jeder Hexenmeister-Talentbaum von Stufe 1 bis 60, zusammengeführt aus Icy Veins, Wowhead und Method; die Schritte eines Baums erscheinen, sobald Sie seine Talentzauber beherrschen. Zieht mit Feuerbrand und Omen der Pein (Zerstörung wirkt Schattenblitz vorab), nutzt Procs von Einbruch der Nacht und Dezimierung, hält Dämonisches Brandmal mit Sengendem Schmerz aufrecht. In Bewegung wirkt sie nur Spontanzauber. Gegen Gruppen: Höllenfeuer in einer Gruppe, Feuerregen, Verderbnis und Pein. Dann Omen der Verdammnis gegen Elitegegner und Bosse oder Omen der Pein, Fluch der Elemente in Gruppen und gegen Elitegegner, Feuerbrand, Verderbnis, Lebensentzug, Feuersbrunst und Schattenbrand; solo füllt sie mit Zermürben, Blutsauger (mit einem Entzugstalent) oder dem Zauberstab; sonst Verbrennen oder Schattenblitz. Erinnerungen: Rüstung, ein Dämon (Sukkubus, sonst Leerwandler, sonst Wichtel), Teufelsbeherrschung, Dämonische Opferung mit Dämonischem Pakt, Seelenverbindung, Waffensteine, Fluch verstärken und Omen der Verwüstung für einen zweiten Gegner. Ihnen überlassen: den Begleiter angreifen lassen, andere Flüche, Furcht, Gesundheitssteine und weitere Ziele. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über das Zeitfenster zum Erledigen (Seelendieb, Schattenbrand als Todesstoß), Aderlass, Lebenslinie und das Entziehen von Leben bei Verletzung."
L["rm.forever.warlock.dps.icyveins.Name"] = "Alle Talentbäume (Icy Veins)"
L["rm.forever.warlock.dps.icyveins.Description"] = "Hexenmeister-Leveling nach Icy Veins: Der Zauberstab ist der Solo-Füller, Leerwandler ist der Standarddämon, Gebrechen und Zerstörung opfern ihren Dämon und spielen ohne (ab 41 bzw. 55), Dämonologie hält Dämonisches Brandmal aufrecht und nutzt Feuerbrand nur als Füller, und Zerstörung setzt Omen der Verwüstung auf den widerstandsfähigsten Gegner einer Gruppe und Feuersbrunst bei Abklingzeit-Ende, sobald Verbrennen bekannt ist. Wählen Sie diese statt der empfohlenen integrierten Hexenmeisterrotation, wenn Sie Icy Veins folgen. Gesundheit, Mana und die Zeit bis zum Tod sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie Blutsauger bei Verletzung, Aderlass und DoTs auf Ziele einsetzen, die lange genug leben. Eine Alternative zur empfohlenen integrierten Hexenmeister-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.forever.warlock.dps.wowhead.Name"] = "Alle Talentbäume (Wowhead)"
L["rm.forever.warlock.dps.wowhead.Description"] = "Hexenmeister auf Stufe 30 nach Wowhead: Gebrechen und Dämonologie betreiben Drain-Tanking mit dem Sukkubus (Verderbnis und Pein, kein Feuerbrand, dann Blutsauger für den Rest des Kampfes; Gesundheit und Mana sind unter Forever verborgen, daher entscheiden Sie selbst über Aderlass), Dämonologie hält Dämonisches Brandmal aufrecht und setzt Pein nur auf große Ziele, Zerstörung setzt Pein, Verderbnis und Feuerbrand auf jeden Gegner, wirkt Feuersbrunst kurz bevor Feuerbrand endet, spart Schattenbrand für den Todesstoß auf und nutzt mit dem Leerwandler den Zauberstab. Fluch verstärken bei jedem Abklingzeit-Ende; Fluch der Elemente und Omen der Verdammnis nur gegen Elitegegner und Bosse; kein Abschnitt für Gruppen von Gegnern. Die Leitfäden von Wowhead enden bei Stufe 30. Eine Alternative zur empfohlenen integrierten Hexenmeister-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.mop.warlock.affliction.Name"] = "Empfohlen"
L["rm.mop.warlock.affliction.Description"] = "Empfohlen für Gebrechen von Stufe 10 bis 90 (gewählt in der Spezialisierung Gebrechen). Wirkt Heimsuchung oder Instabiles Gebrechen vor, eröffnet einen frischen Elitegegner mit Seelenbrand und Seelentausch, hält Agonie, Verderbnis und Instabiles Gebrechen aufrecht (erneuert sie früh, solange Finstere Seele: Elend aktiv ist), wirkt Heimsuchung, wann immer sie zur Neige geht und Sie zwei Splitter haben (oder während Finsterer Seele), kanalisiert Seelendieb für einen Splitter, wenn Heimsuchung ausläuft und Sie keinen haben, Seelendieb unter 20 %, sonst Bösartiger Griff (Schattenblitz vor Stufe 42). Saat der Verderbnis gegen drei oder mehr Gegner (mit Seelenbrand ab sechs). In Bewegung: Spontanzauber und Teufelsflamme. Erinnerungen: Ihr Begleiter, Finstere Absichten, Fluch der Elemente in einer Gruppe, Finstere Seele, Verdammniswache oder Höllenbestie, Grimoire der Dienstbarkeit oder der Opferung, Aderlass, Defensivfähigkeiten. Ihnen überlassen: das Verteilen von DoTs auf andere Ziele und Seelentausch-Übertragungen zwischen ihnen."
L["rm.mop.warlock.affliction.warcrafttavern.Name"] = "Heimsuchung aufsparen (Warcraft Tavern)"
L["rm.mop.warlock.affliction.warcrafttavern.Description"] = "Standardmäßig deaktiviert. Die Splitter-Strategie von Warcraft Tavern und Method: dieselbe DoT-Pflege wie die empfohlene integrierte Gebrechen-Rotation, aber Heimsuchung wird für vier Splitter oder Finstere Seele: Elend aufgespart, und unter 20 % erneuern Seelenbrand und Seelentausch jeden DoT, wann immer Sie einen Splitter haben. Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Gebrechen-Rotation, um sie zu verwenden."
L["rm.mop.warlock.demonology.Name"] = "Empfohlen"
L["rm.mop.warlock.demonology.Description"] = "Empfohlen für Dämonologie von Stufe 10 bis 90 (gewählt in der Spezialisierung Dämonologie). In Zauberergestalt: Verderbnis, Hand von Gul'dan nach Aufladungen, eine zweite Hand von Gul'dan als Übergang in Metamorphose, wenn eine Schattenflamme mit einem Stapel bald ausläuft, Metamorphose mit Finstere Seele: Wissen (oder bei fast vollem Dämonischem Furor), Seelenfeuer bei zwei Stapeln Geschmolzener Kern oder unter 25 %, Höllenfeuer gegen vier oder mehr Gegner, Schattenblitz. In Metamorphose: Verdammnis, Berührung des Chaos, um Verderbnis aufrechtzuerhalten, Seelenfeuer bei Geschmolzener Kern, Feuerbrandaura oder Leerenstrahl gegen Gruppen, Berührung des Chaos und ein Hinweis, sie zu verlassen, wenn Finstere Seele nicht aktiv ist und der Dämonische Furor bei 300 oder weniger liegt. Erinnerungen: Teufelswache (oder Zornwächter), Finstere Absichten, Finstere Seele, Wichtelschwarm, Grimoire: Teufelswache, Verdammniswache oder Höllenbestie, Aderlass, Lebenslinie solo. Ihnen überlassen: Teufelssturm (automatisches Wirken des Begleiters) und Dämonischer Sprung."
L["rm.mop.warlock.demonology.guide.Name"] = "Geschmolzener Kern aufsparen (Leitfäden)"
L["rm.mop.warlock.demonology.guide.Description"] = "Standardmäßig deaktiviert. Der Konsens der Leitfäden (Method, wowtbc.gg, Warcraft Tavern, Wowhead): die empfohlene integrierte Dämonologie-Rotation, außer dass in Zauberergestalt Metamorphose auf 900 Dämonischen Furor oder Finstere Seele wartet und Seelenfeuer nur bei acht Stapeln Geschmolzener Kern oder unter 25 % gewirkt wird, damit die Stapel in Dämonengestalt verbraucht werden. Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Dämonologie-Rotation, um sie zu verwenden."
L["rm.mop.warlock.destruction.Name"] = "Empfohlen"
L["rm.mop.warlock.destruction.Description"] = "Für Zerstörung von Stufe 10 bis 90 (gewählt in der Spezialisierung Zerstörung). Wirkt Verbrennen vor, hält Feuerbrand aufrecht, lässt nie zwei Aufladungen von Feuersbrunst liegen, gibt Instabile Funken für Chaosblitz (Schattenbrand unter 20 %) bei 3,5 Funken oder während Finstere Seele: Instabilität aus, nutzt Pyrolyse für Verbrennen und füllt mit Verbrennen; ein sterbendes Ziel erhält Schattenbrand. Gegen drei oder mehr Gegner: Feuerregen und ab vier Feuer und Schwefel, dann Feuerbrand, Feuersbrunst und Verbrennen, und ein Hinweis, Feuer und Schwefel auszuschalten, wenn Ihre Funken aufgebraucht sind. In Bewegung: Schattenbrand, Feuersbrunst, Teufelsflamme. Erinnerungen: Ihr Begleiter oder Grimoire der Opferung, Flammen von Xoroth, Finstere Absichten, Finstere Seele, Verwüstung gegen zwei oder mehr Gegner (wirken Sie es selbst auf das zweite Ziel), Verdammniswache oder Höllenbestie, Funkenwandlung und Defensivfähigkeiten."
L["rm.mop.warlock.unspecialized.Name"] = "Ohne Spezialisierung"
L["rm.mop.warlock.unspecialized.Description"] = "Für einen Hexenmeister ohne Spezialisierung (Stufe 1 bis 9 oder später, bevor Sie eine wählen). Verderbnis zum Ziehen und aufrechterhalten, Blutsauger unter halber Gesundheit, Schattenblitz. Erinnerungen: der Leerwandler solo (der Wichtel in einer Gruppe) und ein Gesundheitsstein zwischen den Pulls."
L["rm.retail.warlock.affliction.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warlock.affliction.Description"] = "Empfohlen für Gebrechen in Midnight. Im Kampf verbirgt das Spiel nun Ihre DoTs, Procs, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation, die Agonie und Verderbnis aufrechterhält, Seelensplitter für Instabiles Gebrechen ausgibt und Grimoire der Opferung übernimmt) und pausiert, während Sie wirken, kanalisieren oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Dunkelblick beschwören im Kampf, Teufelsjäger beschwören zwischen den Kämpfen, sofern Sie Ihren Dämon nicht geopfert haben, Dämon kommandieren bei einem unterbrechbaren Zauber (es leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt), Dunkler Pakt und Erbarmungslose Entschlossenheit, wann immer sie im Kampf bereit sind (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen)."
L["rm.retail.warlock.affliction.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.warlock.affliction.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft (Seelenernter) liest DoT-Timer, Einbruch der Nacht und Splitterinstabilität, die Midnight im Kampf verbirgt. Heimsuchung vor dem Pull; Saat der Verderbnis gegen drei oder mehr Gegner im Kampf ohne Ihre Verderbnis; Heimsuchung; Agonie und Verderbnis oder Welken unter 3 Sekunden; Dunkle Ernte bei zwei Seelensplittern oder weniger; Instabiles Gebrechen bei 5 Seelensplittern; Bösartiger Griff, sonst Schattenblitz, bei zwei Stapeln Einbruch der Nacht; Instabiles Gebrechen bei Splitterinstabilität oder bei 4 Seelensplittern; Seelendieb; Schattenblitz. Erinnerungen: Dunkelblick beschwören, sobald Dunkle Ernte abklingt, Böswilligkeit, Teufelsjäger beschwören und die gemeinsamen."
L["rm.retail.warlock.demonology.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warlock.demonology.Description"] = "Empfohlen für Dämonologie in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (Schreckenspirscher rufen, Hand von Gul'dan, Dämonenblitz, Kraftentzug und Tyrann) und pausiert, während Sie wirken, kanalisieren oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Dämonischen Tyrannen beschwören, solange die in den letzten 12 Sekunden gerufenen Schreckenspirscher draußen sind, Grimoire: Wichtellord, Grimoire: Teufelsverheerer und Verdammniswache beschwören im Kampf, Teufelswache beschwören zwischen den Kämpfen, Dämon kommandieren, Dunkler Pakt, Erbarmungslose Entschlossenheit."
L["rm.retail.warlock.demonology.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.warlock.demonology.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft (Diaboliker) liest Dämonischen Kern, Wichtelzahlen und Abklingzeit-Timer, die Midnight im Kampf verbirgt. Kraftentzug, Dämonenblitz und Schattenblitz vor dem Pull; dann Kraftentzug bei einem oder keinem Dämonischen Kern, Grimoire: Wichtellord, Grimoire: Teufelsverheerer, Verdammniswache beschwören, Schreckenspirscher rufen, Dämonischen Tyrannen beschwören bei 5 Seelensplittern, Implosion gegen drei oder mehr Gegner im Kampf, Verwüstung, Hand von Gul'dan bei 3 Seelensplittern oder mehr, Höllenblitz unter 3, Dämonenblitz bei Dämonischem Kern unter 4, Schattenblitz."
L["rm.retail.warlock.destruction.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warlock.destruction.Description"] = "Empfohlen für Zerstörung in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (Feuerbrand oder Welken, Feuersbrunst, Chaosblitz, Feuerregen, Seelenfeuer, Böswilligkeit) und pausiert, während Sie wirken, kanalisieren oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Höllenbestie beschwören im Kampf, Wichtel beschwören zwischen den Kämpfen, sofern Sie Ihren Dämon nicht geopfert haben, Dämon kommandieren, Dunkler Pakt, Erbarmungslose Entschlossenheit. Verwüstung auf einem zweiten Ziel bleibt Ihnen überlassen."
L["rm.retail.warlock.destruction.icyveins.Name"] = "Chaosblitz vor dem Maximum, Referenz (Icy Veins)"
L["rm.retail.warlock.destruction.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Höllenrufer-Reihenfolge von Icy Veins, die Seelensplitter für Chaosblitz ausgibt, bevor sie das Maximum erreichen, und Schattenbrand und Dämonenfeuer kanalisieren bei Abklingzeit-Ende nutzt. Feuerregen gegen drei oder mehr Gegner im Kampf; Welken oder Feuerbrand aufrechterhalten; Höllenbestie beschwören; Böswilligkeit; Schattenbrand; Seelenfeuer unter 4 Seelensplittern; Chaosblitz bei 4 oder mehr; Kataklysmus; Höllenblitz unter 4; Dämonenfeuer kanalisieren; Feuersbrunst; Verbrennen."
L["rm.retail.warlock.destruction.simc.Name"] = "Referenz (SimulationCraft)"
L["rm.retail.warlock.destruction.simc.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von SimulationCraft liest Feuerbrand, Pyrolyse, Aufladungen und Abklingzeit-Timer, die Midnight im Kampf verbirgt. Seelenfeuer und Verbrennen vor dem Pull; gegen drei oder mehr Gegner im Kampf Feuerregen bei 3 Seelensplittern und Kataklysmus; dann Seelenfeuer bei 4 Seelensplittern oder weniger, Chaosblitz nur bei 5, Feuersbrunst bei zwei Aufladungen oder unter 4 Seelensplittern ohne Pyrolyse, Höllenbestie beschwören, Böswilligkeit, Welken oder Feuerbrand in seinen letzten 30 %, Verwüstung, Kataklysmus, Höllenblitz bei 3 Seelensplittern oder weniger, Verbrennen."
L["rm.retail.warlock.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warlock.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Hexenmeisters meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Hexenmeister-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.sod.warlock.fire.Name"] = "Feuer (SoD)"
L["rm.sod.warlock.fire.Description"] = "Zerstörung in der Saison der Entdeckungen, gewählt, sobald Chaosblitz oder Verbrennen graviert ist; zusammengestellt aus Simulation Phase 6 und Wowhead. Schattenbrand und Sengender Schmerz zum Erledigen; Spontanzauber in Bewegung; der Stärkungszauber von Verbrennen, See des Feuers und Höllenfeuer gegen Gruppen; ein Fluch (Tollkühnheit in einer Gruppe, wenn niemand ihn wirkt, Fluch der Verdammnis bei langen Kämpfen gegen Elitegegner, sonst Fluch der Pein); Feuersbrunst nur, um Pyrolyse zu halten; Feuerbrand und der Stärkungszauber von Verbrennen aufrechterhalten; unter 35 % Seelenfeuer während Dezimierung statt Chaosblitz; Procs von Seelenfeuer!; Chaosblitz; solo Blutsauger mit Meisterkanalisierer und Aderlass; Verbrennen (Schattenblitz, bevor Sie es gravieren). Erinnerungen: Teufelsrüstung, der Wichtel, Fluch verstärken und die Sicherheitserinnerungen."
L["rm.sod.warlock.fire.icyveins.Name"] = "Feuer, Feuersbrunst bei Abklingzeit-Ende (SoD, Icy Veins)"
L["rm.sod.warlock.fire.icyveins.Description"] = "Zerstörung in der Saison der Entdeckungen nach Icy Veins und Warcraft Tavern, eine Alternative zur empfohlenen integrierten Feuerrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Feuerbrand aufrechterhalten, Feuersbrunst und Chaosblitz bei Abklingzeit-Ende (Chaosblitz auch unter 35 %), der Stärkungszauber von Verbrennen, Seelenfeuer während Dezimierung unter 35 %, Verbrennen als Füller; der Schadensfluch nur in Bewegung, mit Tollkühnheit in einer Gruppe, wenn niemand ihn wirkt."
L["rm.sod.warlock.shadow.Name"] = "Schatten, Gebrechen und Teufelswache (SoD)"
L["rm.sod.warlock.shadow.Description"] = "Gebrechen- und Teufelswachen-Builds in der Saison der Entdeckungen und jeder Hexenmeister der Saison der Entdeckungen, zu dem keine andere integrierte Rotation passt; zusammengestellt aus Simulation Phase 6, Wowhead und Icy Veins. Procs von Einbruch der Nacht; Schattenbrand oder Seelendieb, um ein Ziel in der Gruppe zu erledigen; ein sterbendes Solo-Ziel erhält Seelendieb, keine DoTs; Spontanzauber in Bewegung; See des Feuers und Höllenfeuer gegen Gruppen; ein Fluch (Tollkühnheit in einer Gruppe, wenn niemand ihn wirkt, sonst Fluch der Pein); Instabiles Gebrechen, Blutsauger mit Meisterkanalisierer, Schattenflamme (davor Feuerbrand), Verderbnis, Heimsuchung, Lebensentzug (jeweils unter 6 Sekunden erneuert, wenn Herbeirufung graviert ist); Seelendieb unter 20 %, wenn Seelenentzug graviert ist; Durchhalten im Solospiel und der Zauberstab; Schattenblitz. Erinnerungen: Teufelsrüstung, Ihr Begleiter (eine Teufelswache, sobald graviert), Aderlass für einen Begleiter mit wenig Mana, Fluch verstärken und die Sicherheitserinnerungen. Fluchzuweisungen und Schattenblitzsalve gegen Gruppen bleiben Ihnen überlassen."
L["rm.sod.warlock.shadow.simulator.Name"] = "Schatten, Seelendieb als Füller (SoD, Simulation)"
L["rm.sod.warlock.shadow.simulator.Description"] = "Die Gebrechen-Liste von Simulation für Phase 6 für einen Seelenentzug-Build, eine Alternative zur empfohlenen integrierten Schattenrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Seelendieb ist bei jeder Gesundheit der Füller, und der nächste Schritt erscheint, sobald er fällig ist, damit Sie die Kanalisierung dafür abbrechen können; jede andere Kanalisierung wird zu Ende geführt. Instabiles Gebrechen und Schattenflamme bei 7,5 verbleibenden Sekunden erneuert, Fluch der Pein und Verderbnis bei 6, Blutsauger mit Meisterkanalisierer, Heimsuchung, Schattenblitz nur bei einem Proc von Schattentrance, Lebensentzug, Aderlass unter 10 % Mana. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.sod.warlock.tank.Name"] = "Tank, Metamorphose (SoD)"
L["rm.sod.warlock.tank.Description"] = "Tank in der Saison der Entdeckungen, gewählt, sobald Metamorphose graviert ist; zusammengestellt aus Simulation, Icy Veins, Wowhead und Warcraft Tavern. Schattenspalten, wann immer Entschluss des Verteidigers fehlt oder ausläuft, ein Proc von Seelenfeuer!, Verbrennen, um seinen Feuer-Stärkungszauber zu halten; gegen drei oder mehr Gegner Schattenspalten, See des Feuers, Schattenflamme und Höllenfeuer. Dann ein Fluch (Fluch der Pein, sonst Tollkühnheit, wenn niemand ihn wirkt), Schattenflamme (Feuerbrand, bevor Sie sie gravieren), Blutsauger mit Meisterkanalisierer, Verderbnis, Lebensentzug, Feuersbrunst für Pyrolyse, Seelenfeuer während Dezimierung unter 35 % und Sengender Schmerz als Bedrohungsfüller. Erinnerungen: Metamorphose, Teufelsrüstung, Ihr Begleiter, Feuerbrandaura, Dämonische Anmut, Rache bei niedriger Gesundheit, Plagegeist, wenn das Ziel jemand anderen angreift, Dämonisches Heulen gegen Gruppen, Fluch verstärken, Aderlass für einen Begleiter mit wenig Mana. Höllische Rüstung bleibt Ihnen überlassen."
L["rm.tbc.warlock.dps.icyveins.Name"] = "Alle Talentbäume (Icy Veins)"
L["rm.tbc.warlock.dps.icyveins.Description"] = "Jeder Talentbaum von Stufe 1 bis 70. Fluch, dann Instabiles Gebrechen, Feuerbrand, Verderbnis und Lebensentzug, sobald erlernt, Schattenblitz oder Verbrennen; Procs von Einbruch der Nacht und Heimzahlen zuerst; Saat der Verderbnis, Höllenfeuer und Schattenfurie für drei oder mehr Gegner. Solo entzieht sie Leben, wenn Sie verletzt sind, nutzt Aderlass, den Zauberstab und Seelendieb oder einen Finisher auf ein sterbendes Ziel. Erinnerungen: Teufelsrüstung, Dämonenrüstung oder Dämonenhaut, Ihr Dämon, Opferung, Seelenverbindung, Fluch verstärken und Seele brechen. Furcht und andere Flüche bleiben Ihnen überlassen."
L["rm.tbc.warlock.dps.wowhead.Name"] = "Drain-Tanking (Wowhead)"
L["rm.tbc.warlock.dps.wowhead.Description"] = "Hexenmeister nach den Leitfäden von Wowhead, eine Alternative zur empfohlenen integrierten Hexenmeister-Rotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Solo betreibt sie Drain-Tanking: Blutsauger ist der Füller, sobald Ihre DoTs wirken, und Feuerbrand und Lebensentzug werden für Elitegegner aufgespart. In einer Gruppe kommt Feuerbrand immer zum Einsatz, nach Verderbnis und Lebensentzug. Ansonsten wie die empfohlene integrierte Rotation."
